const { test, expect } = require('@playwright/test');

test('loads data on button click', async ({ page }) => {
  await page.goto('http://localhost:8080/flaky.html');
  await page.click('#loadBtn');
  // Wait for a network response that indicates data loading is complete
  await page.waitForResponse(response => response.url().includes('/data') && response.status() === 200);
  const text = await page.textContent('#result');
  expect(text).toBe('Data Loaded');
});
